// Writes dist/.htaccess for WPX (LiteSpeed/Apache): old-URL redirects and security headers, both read from vercel.json
// so the Vercel preview and WPX behave the same. SITE_ENV=staging adds noindex and blocks crawlers.
import { readFileSync, writeFileSync } from 'node:fs';

const cfg = JSON.parse(readFileSync(new URL('../vercel.json', import.meta.url), 'utf8'));
const staging = process.env.SITE_ENV === 'staging';
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const lines = [
  '# Generated by scripts/htaccess.mjs: edit vercel.json, not this file.',
  'Options -Indexes',
  'DirectoryIndex index.html index.php',
  'ErrorDocument 404 /404.html',
  'AddDefaultCharset utf-8',
  '',
  '<IfModule mod_rewrite.c>',
  'RewriteEngine On',
  '# No www (WPX forces HTTPS itself; checking %{HTTPS} here can loop behind its CDN)',
  'RewriteCond %{HTTP_HOST} ^www\\.(.+)$ [NC]',
  'RewriteRule ^ https://%1%{REQUEST_URI} [R=301,L,NE]',
  '# Never serve dotfiles or the PHP config',
  'RewriteRule (^|/)\\.(?!well-known/) - [F,L]',
  '',
  '# Old WordPress addresses',
];
const seen = new Set();
for (const r of cfg.redirects) {
  let src = r.source;
  let pattern;
  if (src.includes(':year')) pattern = '^\\d{4}/\\d{2}/.*$';
  else if (src.includes(':path*')) pattern = '^' + esc(src.slice(1).replace(/\/?:path\*$/, '')) + '(?:/.*)?$';
  else pattern = '^' + esc(src.slice(1).replace(/\/$/, '')) + '/?$';
  if (src.startsWith('/tickets-')) pattern = '^tickets-.*$';
  if (seen.has(pattern)) continue;
  seen.add(pattern);
  const [path, query] = r.destination.split('?');
  lines.push(`RewriteRule ${pattern} ${path}${query ? '?' + query : ''} [R=301,L,NE${query ? ',QSD' : ''}]`);
}
lines.push(
  '',
  '# Add the trailing slash the site uses everywhere',
  'RewriteCond %{REQUEST_FILENAME} !-f',
  'RewriteCond %{REQUEST_URI} !/$',
  'RewriteCond %{REQUEST_FILENAME}/index.html -f',
  'RewriteRule ^(.*)$ /$1/ [R=301,L]',
  '</IfModule>',
  '',
  '<IfModule mod_headers.c>',
);
const all = cfg.headers.find((h) => h.source === '/(.*)' && !h.missing);
for (const h of all.headers) lines.push(`Header always set ${h.key} "${h.value.replace(/"/g, '\\"')}"`);
if (staging) lines.push('Header always set X-Robots-Tag "noindex, nofollow"');
lines.push(
  '<FilesMatch "\\.html$">',
  '  Header set Cache-Control "public, max-age=0, must-revalidate"',
  '</FilesMatch>',
  '</IfModule>',
  '',
  '<IfModule mod_expires.c>',
  'ExpiresActive On',
  'ExpiresByType text/html "access plus 0 seconds"',
  '</IfModule>',
  '',
);
// Hashed build assets never change: cache them for a year.
writeFileSync(new URL('../dist/_astro/.htaccess', import.meta.url), '<IfModule mod_headers.c>\nHeader set Cache-Control "public, max-age=31536000, immutable"\n</IfModule>\n<IfModule mod_expires.c>\nExpiresActive Off\n</IfModule>\n');
writeFileSync(new URL('../dist/.htaccess', import.meta.url), lines.join('\n'));
if (staging) writeFileSync(new URL('../dist/robots.txt', import.meta.url), 'User-agent: *\nDisallow: /\n');
console.log(`.htaccess written (${seen.size} redirects${staging ? ', staging: noindex' : ''})`);
